const DISTANCES = new Uint16Array(13530);
for (let i = 0; i < DISTANCES.length; i++) {
  const at = i * 3;
  DISTANCES[i] = DIGITS.indexOf(PACKED[at]) << 12 | DIGITS.indexOf(PACKED[at + 1]) << 6 | DIGITS.indexOf(PACKED[at + 2]);
}

export function distanceKm(a: number, b: number): number {
  if (!Number.isInteger(a) || !Number.isInteger(b) ||
      a < 0 || b < 0 || a >= DISTANCE_CITY_COUNT || b >= DISTANCE_CITY_COUNT) {
    throw new RangeError('City index out of range');
  }
  if (a === b) return 0;
  const hi = a > b ? a : b;
  const lo = a < b ? a : b;
  return DISTANCES[hi * (hi - 1) / 2 + lo];
}
